begin;
create temp table _had_parking on commit drop as select id from public.areas where parking_lat is not null;
update public.areas set parking_lat=33.679591, parking_lng=-112.037915, parking_name='Dead-end lot at the end of Lone Cactus Road (small, ~5 cars)' where path <@ (select path from public.areas where id='az_beardsley_boulders_area') and id not in (select id from _had_parking) and (lat is null or lng is null or 12742 * asin(sqrt(power(sin(radians(lat - 33.679591) / 2), 2) + cos(radians(33.679591)) * cos(radians(lat)) * power(sin(radians(lng - -112.037915) / 2), 2))) <= 4);
